"use strict";
// What library code reads from an error it is handed, one fact per line.
const util = require("node:util");
const { EventEmitter } = require("node:events");

const show = (v) => {
  if (typeof v === "string") return JSON.stringify(v);
  if (typeof v === "function") return "fn:" + v.name;
  if (v instanceof Error) return "<" + v.name + ": " + v.message + ">";
  if (v !== null && typeof v === "object") return JSON.stringify(v);
  return String(v);
};
const desc = (o, k) => {
  const d = Object.getOwnPropertyDescriptor(o, k);
  if (d === undefined) return "-";
  return ("value" in d ? "data:" : "accessor:") + (d.writable ? "w" : "-") + (d.enumerable ? "e" : "-") + (d.configurable ? "c" : "-");
};
const classes = { Error, TypeError, RangeError, SyntaxError, ReferenceError, EvalError, URIError, AggregateError, DOMException };
const lines = (label, facts) => {
  const out = [];
  for (const [name, read] of facts) {
    let text;
    try {
      text = String(read());
    } catch (x) {
      text = "!" + x.name + ": " + x.message;
    }
    out.push(label + " " + name + " = " + text);
  }
  return out.join("\n");
};

// The own properties, class and standard reflections of an error.
exports.view = (label, e) =>
  lines(label, [
    ["own", () => Object.getOwnPropertyNames(e).join(",")],
    ["keys", () => Object.keys(e).join(",")],
    ["for-in", () => { const ks = []; for (const k in e) ks.push(k); return ks.join(","); }],
    ["message", () => Object.hasOwn(e, "message") + " " + ("message" in e) + " " + desc(e, "message") + " " + show(e.message)],
    ["name", () => Object.hasOwn(e, "name") + " " + desc(e, "name") + " " + show(e.name)],
    ["stack", () => Object.hasOwn(e, "stack") + " " + desc(e, "stack") + " " + typeof e.stack + " " + show(String(e.stack).split("\n")[0])],
    ["cause", () => Object.hasOwn(e, "cause") + " " + ("cause" in e) + " " + desc(e, "cause") + " " + show(e.cause)],
    ["code", () => Object.hasOwn(e, "code") + " " + desc(e, "code") + " " + show(e.code)],
    ["errors", () => Object.hasOwn(e, "errors") + " " + desc(e, "errors") + " " + (e.errors === undefined ? "undefined" : Array.isArray(e.errors) + ":" + e.errors.map(show).join(","))],
    ["instanceof", () => Object.keys(classes).filter((k) => e instanceof classes[k]).join(",")],
    ["constructor", () => Object.keys(classes).filter((k) => e.constructor === classes[k]).join(",")],
    ["prototype", () => Object.keys(classes).filter((k) => Object.getPrototypeOf(e) === classes[k].prototype).join(",")],
    ["tag", () => Object.prototype.toString.call(e) + " " + util.types.isNativeError(e)],
    ["String", () => String(e)],
    ["json", () => JSON.stringify(e)],
    ["entries", () => Object.entries(e).map(([k, v]) => k + ":" + show(v)).join(",")],
    ["spread", () => Object.keys({ ...e }).join(",")],
    ["clone", () => { const c = structuredClone(e); return c.constructor.name + " " + show(c.name) + " " + show(c.message) + " " + Object.getOwnPropertyNames(c).join(",") + " " + show(c.cause); }],
    ["extensible", () => Object.isExtensible(e) + " " + Object.isFrozen(e)],
  ]);

// The own properties of a program class instance and what names it.
exports.fields = (label, e) =>
  lines(label, [
    ["own", () => Object.getOwnPropertyNames(e).join(",")],
    ["keys", () => Object.keys(e).join(",")],
    ["message", () => Object.hasOwn(e, "message") + " " + desc(e, "message") + " " + show(e.message)],
    ["name", () => Object.hasOwn(e, "name") + " " + desc(e, "name") + " " + show(e.name)],
    ["stack", () => desc(e, "stack") + " " + show(String(e.stack).split("\n")[0])],
    ["instanceof", () => Object.keys(classes).filter((k) => e instanceof classes[k]).join(",")],
    ["tag", () => Object.prototype.toString.call(e) + " " + util.types.isNativeError(e)],
    ["String", () => String(e)],
    ["json", () => JSON.stringify(e)],
    ["entries", () => Object.entries(e).map(([k, v]) => k + ":" + show(v)).join(",")],
  ]);

// A program class instance: its fields and what its class holds.
exports.members = (label, e, Class, names) => {
  const facts = [];
  for (const k of names) {
    facts.push([k, () => typeof e[k] + " " + Object.hasOwn(e, k) + " " + (k in e) + " " + desc(e, k) + " " + show(typeof e[k] === "function" ? e[k]() : e[k])]);
  }
  facts.push(["instanceof class", () => e instanceof Class]);
  return lines(label, facts);
};
exports.isInstance = (e, Class) => e instanceof Class;

// Identity.
const kept = new Map();
exports.keep = (slot, e) => { kept.set(slot, e); return e; };
exports.same = (slot, e) => kept.get(slot) === e;
exports.giveBack = (e) => e;
exports.catchSame = (slot, f) => { try { f(); return "no throw"; } catch (e) { return String(kept.get(slot) === e); } };
exports.wrap = (e) => ({ e });
exports.list = (...es) => es;
exports.settledSame = async (slot, ps) => (await Promise.allSettled(ps)).map((r) => r.status + ":" + (r.reason === kept.get(slot))).join(",");
exports.settle = (ps) => Promise.allSettled(ps);
exports.emitter = () => new EventEmitter();
exports.listenSame = (em, slot) => { let seen = "none"; em.on("error", (e) => { seen = String(kept.get(slot) === e); }); return () => seen; };
exports.emitError = (em, e) => em.emit("error", e);
exports.causeIs = (outer, inner) => outer.cause === inner;
exports.errorsAt = (agg, i, inner) => agg.errors[i] === inner;

// Writes island code makes.
exports.tag = (e) => { e.handled = true; e.code = "E_TAGGED"; e.message = "tagged"; };
exports.write = (e, k, v) => { e[k] = v; return e[k] === v; };
exports.remove = (e, k) => delete e[k];
exports.readKept = (slot, k) => show(kept.get(slot)[k]);
exports.keysKept = (slot) => Object.keys(kept.get(slot)).join(",");
exports.rethrowTagged = (f) => { try { f(); } catch (e) { e.status = 500; e.retried = true; throw e; } };
exports.logger = () => {
  const seen = [];
  return {
    error(err) { err.logged = (err.logged ?? 0) + 1; seen.push(err.name + ": " + err.message); },
    lines: () => seen.join("; "),
  };
};

// Island errors, for the other direction.
exports.make = (kind) => {
  switch (kind) {
    case "plain": return new Error("m");
    case "type": return new TypeError("t");
    case "props": return Object.assign(new Error("m"), { code: "E_X", detail: { n: 1 } });
    case "aggregate": return new AggregateError([new Error("e1"), new TypeError("e2")], "many");
    case "dom": return new DOMException("gone", "AbortError");
    default: throw new Error("unknown kind " + kind);
  }
};
exports.makeKept = (slot, kind) => { const e = exports.make(kind); kept.set(slot, e); return e; };
exports.throwKept = (slot) => { throw kept.get(slot); };
exports.islandValue = () => ({ island: true });
